public int CarFleet(int target, int[] position, int[] speed)
{
    int n = position.Length;

    // Pair each car with its arrival time, then sort by position
    var cars = new (int Position, double ArrivalTime)[n];

    for (int i = 0; i < n; i++)
    {
        double arrivalTime = (double)(target - position[i]) / speed[i];
        cars[i] = (position[i], arrivalTime);
    }

    Array.Sort(cars, (a, b) => a.Position.CompareTo(b.Position));

    int fleets = 0;
    double slowestFleetTime = 0;

    // Walk from the car nearest the target back to the furthest
    for (int i = n - 1; i >= 0; i--)
    {
        double arrivalTime = cars[i].ArrivalTime;

        // This car does not catch the fleet ahead of it
        if (arrivalTime > slowestFleetTime)
        {
            fleets++;
            slowestFleetTime = arrivalTime;
        }
    }

    return fleets;
}

public int CarFleetStack(int target, int[] position, int[] speed)
{
    int n = position.Length;
    var order = Enumerable.Range(0, n)
        .OrderByDescending(i => position[i])
        .ToArray();

    var stack = new Stack<double>();

    foreach (int i in order)
    {
        double arrivalTime = (double)(target - position[i]) / speed[i];

        // If this car arrives sooner, it merges with the fleet on top
        while (stack.Count > 0 && arrivalTime <= stack.Peek())
        {
            break; // merging only ever affects the top fleet in this formulation
        }

        stack.Push(arrivalTime);
    }

    return stack.Count;
}

public int CarFleet(int target, int[] position, int[] speed)
{
    int n = position.Length;
    var cars = new (int Position, double Time)[n];

    for (int i = 0; i < n; i++)
        cars[i] = (position[i], (double)(target - position[i]) / speed[i]);

    Array.Sort(cars, (a, b) => a.Position.CompareTo(b.Position));

    int fleets = 0;
    double slowestFleetTime = 0;

    for (int i = n - 1; i >= 0; i--)
    {
        if (cars[i].Time > slowestFleetTime)
        {
            fleets++;
            slowestFleetTime = cars[i].Time;
        }
    }

    return fleets;
}
